@@ -30,3 +38,25 @@ export function t(key, lang = "en", params = {}) {

 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** The supported language the Accept-Language header prefers most, else `fallback`. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  if (typeof header !== "string") return fallback;
+  let best = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [tag, ...attrs] = part.trim().split(";");
+    let q = 1;
+    for (const attr of attrs) {
+      const m = /^\s*q\s*=\s*([0-9.]+)\s*$/i.exec(attr);
+      if (m) q = Number(m[1]);
+    }
+    if (!(q > 0 && q <= 1)) continue;
+    const lang = tag.trim().toLowerCase().split("-")[0];
+    if (LANGUAGES.includes(lang) && q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
