+++ b/tests/i18n.test.js
@@ -0,0 +1,29 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+import { CODES } from "../src/errors.js";
+import { messageKeys, pickLanguage } from "../src/i18n/messages.js";
+
+test("every error code has a Korean message", () => {
+  const ko = messageKeys("ko");
+  for (const code of Object.keys(CODES)) assert.ok(ko.includes(code), code);
+});
+
+test("Accept-Language picks the language", () => {
+  assert.equal(pickLanguage("ko", "en"), "ko");
+  assert.equal(pickLanguage("ko-KR,ko;q=0.9,en;q=0.8", "en"), "ko");
+  assert.equal(pickLanguage("en;q=0.5, ko;q=0.8", "en"), "ko");
+  assert.equal(pickLanguage("ko;q=0.5, en-US", "ko"), "en");
+  assert.equal(pickLanguage("ko;q=0, en;q=0.1", "ko"), "en");
+  assert.equal(pickLanguage("fr-FR, de", "ko"), "ko");
+  assert.equal(pickLanguage(undefined, "ko"), "ko");
+  assert.equal(pickLanguage("", "en"), "en");
+});
+
+test("errors answer in the request's language", async () => {
+  const { handle } = app();
+  const ko = await handle({ path: "/items/99", headers: { "accept-language": "ko-KR,en;q=0.5" } });
+  assert.equal(ko.body.error.message, "99번 품목이 없습니다.");
+  const en = await handle({ path: "/items/99", headers: { "Accept-Language": "en-GB" } });
+  assert.equal(en.body.error.message, "There is no item 99.");
+});
